/**
 * 终端资源路由：命令执行（/exec）与终止（/exec-kill）。
 *
 * 会话级工作目录（cd 由服务端维护）与运行中进程表收敛在本模块内部，
 * 与其它资源路由解耦。
 */
import { spawn, type ChildProcess } from "node:child_process";
import { stat } from "node:fs/promises";
import { resolve } from "node:path";
import { homedir } from "node:os";

import { FsError, isProtectedPath, requireAbsolute } from "./fs-tree.js";
import { getRoot } from "./root-store.js";
import {
  json,
  readBody,
  type RouteMatcher,
} from "./routes-util.js";

/** 终端会话 → 当前工作目录（会话级记忆，cmd /c 不保留目录切换，故由服务端维护）。 */
const sessionCwd = new Map<string, string>();

/** 终端会话 → 正在运行的子进程（供 Ctrl+C 终止）。 */
const sessionProc = new Map<string, ChildProcess>();

/** 终端单条命令执行结果。 */
export interface ExecResult {
  /** 进程退出码；-1 表示超时或启动失败。 */
  code: number;
  stdout: string;
  stderr: string;
  /** 执行是否因超时被终止。 */
  timedOut?: boolean;
}

/** 终止命令进程树（Windows 用 taskkill 连子进程一起结束，避免残留）。 */
function killTree(child: ChildProcess): void {
  if (process.platform === "win32" && child.pid) {
    spawn("taskkill", ["/pid", String(child.pid), "/t", "/f"], { stdio: "ignore", windowsHide: true });
  } else {
    child.kill("SIGTERM");
  }
}

/**
 * 危险破坏性命令特征（小写子串匹配）。命中任一即拒绝执行，防止递归/强制删除、
 * 格式化、关机重启等误操作或恶意调用波及系统。
 */
const DANGEROUS_COMMAND_MARKERS = [
  "rm -rf",
  "rm -fr",
  "rm -r -f",
  "rm -f -r",
  "rm --recursive --force",
  "rm --force --recursive",
  "rd /s",
  "rmdir /s",
  "del /s",
  "deltree",
  "remove-item -recurse",
  "remove-item -r",
  "remove-item -force",
  "clear-recyclebin -force",
  "format c:",
  "format d:",
  "format c /",
  "mkfs",
  "diskpart",
  "shutdown",
  "reboot",
  "poweroff",
  " halt ",
  "reg delete",
  "cipher /w",
];

/** 判断终端命令是否命中危险黑名单（整条命令子串匹配，覆盖 `cd /d ... && rm -rf /` 拼接）。 */
function isDangerousCommand(command: string): boolean {
  const lower = command.toLowerCase();
  return DANGEROUS_COMMAND_MARKERS.some((marker) => lower.includes(marker));
}

/** 支持的终端 shell：cmd（默认）或 powershell。 */
export type TermShell = "cmd" | "powershell";

/** 运行一条 shell 命令（Windows 用 cmd /c 或 powershell -Command，其余用 sh -c），带超时保护；会话内进程可被 Ctrl+C 终止。 */
export function runShell(
  command: string,
  cwd: string,
  session: string,
  opts: { shell?: TermShell; timeout?: number } = {},
): Promise<ExecResult> {
  return new Promise((resolvePromise) => {
    const timeoutMs = opts.timeout ?? 60000;
    const isWin = process.platform === "win32";
    const shell = opts.shell === "powershell" ? "powershell" : "cmd";
    let child: ChildProcess;
    if (!isWin) {
      child = spawn("sh", ["-c", command], { cwd, stdio: ["ignore", "pipe", "pipe"], env: process.env });
    } else if (shell === "powershell") {
      // cmd 不再需要；PowerShell 需保证 UTF-8 输出编码，避免中文乱码
      const psFinal = `\$OutputEncoding=[Console]::OutputEncoding=[Text.Encoding]::UTF8; ${command}`;
      child = spawn("powershell.exe", ["-NoProfile", "-NonInteractive", "-Command", psFinal], {
        cwd,
        windowsHide: true,
        stdio: ["ignore", "pipe", "pipe"],
        env: process.env,
      });
    } else {
      const cmdFinal = `chcp 65001>nul && ${command}`;
      child = spawn("cmd.exe", ["/c", cmdFinal], { cwd, windowsHide: true, stdio: ["ignore", "pipe", "pipe"], env: process.env });
    }
    sessionProc.set(session, child);
    const stdoutBufs: Buffer[] = [];
    const stderrBufs: Buffer[] = [];
    let settled = false;
    const settle = (result: ExecResult) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (sessionProc.get(session) === child) sessionProc.delete(session);
      resolvePromise(result);
    };
    const timer = setTimeout(() => {
      if (settled) return;
      killTree(child);
      settle({ code: -1, stdout: Buffer.concat(stdoutBufs).toString("utf8"), stderr: Buffer.concat(stderrBufs).toString("utf8"), timedOut: true });
    }, Math.max(1000, Math.min(timeoutMs, 600000)));
    child.stdout?.on("data", (d: Buffer) => { stdoutBufs.push(d); });
    child.stderr?.on("data", (d: Buffer) => { stderrBufs.push(d); });
    child.on("error", (err) => {
      settle({ code: -1, stdout: Buffer.concat(stdoutBufs).toString("utf8"), stderr: Buffer.concat(stderrBufs).toString("utf8") || err.message });
    });
    child.on("close", (code) => {
      settle({ code: code ?? -1, stdout: Buffer.concat(stdoutBufs).toString("utf8"), stderr: Buffer.concat(stderrBufs).toString("utf8") });
    });
  });
}

/** 资源路由：终端命令执行 + 终止。 */
export const terminalResource: RouteMatcher = async (req, res, seg, _q, method, host) => {
  void host;
  // --- 执行一条 cmd/sh 命令（会话级工作目录，cd 由服务端维护） ---
  if (seg[0] === "exec" && seg.length === 1 && method === "POST") {
    const body = (await readBody(req)) as
      | { key?: string; session?: string; command?: string; cwd?: string; timeout?: number; shell?: TermShell }
      | null;
    const command = (body?.command ?? "").trim();
    if (!command) return (json(res, 400, { ok: false, error: "command required" }), true);
    const session = body?.session?.trim() || "default";
    const shell: TermShell = body?.shell === "powershell" ? "powershell" : "cmd";
    let cwd = body?.cwd?.trim() || sessionCwd.get(session) || getRoot(body?.key) || homedir();
    cwd = requireAbsolute(cwd);
    // 受保护只读目录（如 C:\Windows 整棵）：禁止在其内执行命令，防止绕过文件写保护。
    if (isProtectedPath(cwd)) {
      throw new FsError("forbidden", "command rejected: working directory is a protected read-only area", 403);
    }

    // cd / chdir：只更新会话目录，不真正派生子进程（cmd /c 不保留目录切换）
    const cdMatch = command.match(/^(?:cd|chdir)\b(.*)$/i);
    if (cdMatch) {
      let target = (cdMatch[1] ?? "").trim();
      target = target.replace(/^\/d\s+/i, "");
      const next = target ? resolve(cwd, target) : homedir();
      if (isProtectedPath(next)) {
        return (json(res, 200, { ok: true, data: { code: 1, stdout: "", stderr: `cd: "${target}": access denied (protected read-only area)`, cwd } }), true);
      }
      const st = await stat(next).catch(() => null);
      if (!st || !st.isDirectory()) {
        return (json(res, 200, { ok: true, data: { code: 1, stdout: "", stderr: `cd: "${target}": no such directory`, cwd } }), true);
      }
      sessionCwd.set(session, next);
      return (json(res, 200, { ok: true, data: { code: 0, stdout: "", stderr: "", cwd: next } }), true);
    }

    // 破坏性命令黑名单拦截：命中直接拒绝，不派生子进程。
    if (isDangerousCommand(command)) {
      throw new FsError("forbidden", `command rejected: potentially destructive (recursive delete / format / shutdown)`, 403);
    }

    // 同一会话只允许一个运行中的进程：先终止旧的再执行新的
    const prev = sessionProc.get(session);
    if (prev) killTree(prev);
    const result = await runShell(command, cwd, session, { shell, timeout: body?.timeout });
    return (json(res, 200, { ok: true, data: { ...result, cwd } }), true);
  }

  // --- 终止终端会话正在运行的命令（Ctrl+C） ---
  if (seg[0] === "exec-kill" && seg.length === 1 && method === "POST") {
    const body = (await readBody(req)) as { session?: string } | null;
    const session = body?.session?.trim() || "default";
    const child = sessionProc.get(session);
    if (child) {
      killTree(child);
      return (json(res, 200, { ok: true, data: { killed: true } }), true);
    }
    return (json(res, 200, { ok: true, data: { killed: false } }), true);
  }

  return false;
};