/**
 * 文件工作台 —— 子代理会话跨重启持久化（按 DSH 会话 key）。
 *
 * 每个 DSH 会话（sessionId）对应一个 JSON 文件，内含该会话开启的全部子代理：
 *   {DSH_HOME | ~/.dsh}/fileworkbench/subagent-chat/<sessionId>.json
 * 内容为 { entries: SubagentChatEntry[] }（每个子代理 = 一条独立对话，含名称/目标/轮次）。
 *
 * sessionId 会被清理（仅保留字母数字 - _ .），避免路径穿越。
 */
import { readFile, writeFile, mkdir, unlink } from "node:fs/promises";
import { join } from "node:path";
import { homedir } from "node:os";
import type { AgentTurn, SessionSubagentChats, SubagentChatEntry } from "../shared/types.js";

/** 持久化文件存放目录：{DSH_HOME | ~/.dsh}/fileworkbench/subagent-chat/。 */
function chatDir(): string {
  const dshHome = process.env.DSH_HOME || join(homedir(), ".dsh");
  return join(dshHome, "fileworkbench", "subagent-chat");
}

/** 清理会话 id，仅保留安全字符，防路径穿越。 */
function safeId(sessionId: string): string {
  const cleaned = sessionId.replace(/[^a-zA-Z0-9._-]/g, "_").slice(0, 96);
  return cleaned || "default";
}

/** 消化单条入口，保证字段齐全。 */
function normalizeEntry(e: unknown): SubagentChatEntry | undefined {
  if (!e || typeof e !== "object") return undefined;
  const o = e as Record<string, unknown>;
  const turns = Array.isArray(o.turns)
    ? (o.turns as unknown[]).filter(
        (t): t is AgentTurn =>
          !!t &&
          typeof t === "object" &&
          ((t as { role?: unknown }).role === "user" || (t as { role?: unknown }).role === "assistant") &&
          typeof (t as { content?: unknown }).content === "string",
      )
    : [];
  return {
    id: typeof o.id === "string" && o.id ? o.id : (typeof o.path === "string" ? o.path : "anon"),
    name: typeof o.name === "string" && o.name ? o.name : (typeof o.path === "string" ? o.path : "子代理"),
    path: typeof o.path === "string" ? o.path : "",
    isDir: o.isDir === true,
    turns,
    createdAt: typeof o.createdAt === "number" ? o.createdAt : Date.now(),
    updatedAt: typeof o.updatedAt === "number" ? o.updatedAt : Date.now(),
  };
}

/** 读取某会话的子代理列表（不存在/损坏返回空列表）。兼容旧版单对话形状。 */
export async function getSessionSubagents(sessionId: string): Promise<SessionSubagentChats> {
  const file = join(chatDir(), `${safeId(sessionId)}.json`);
  try {
    const parsed = JSON.parse(await readFile(file, "utf8")) as SessionSubagentChats & Partial<SubagentChatEntry>;
    if (Array.isArray(parsed.entries)) {
      return { entries: parsed.entries.map(normalizeEntry).filter((e): e is SubagentChatEntry => !!e) };
    }
    // 旧版单对话形状：{ path, isDir, turns } 迁移成一条子代理。
    if (Array.isArray(parsed.turns)) {
      const legacy: SubagentChatEntry = {
        id: typeof parsed.path === "string" ? parsed.path : "legacy",
        name: typeof parsed.path === "string" ? parsed.path : "子代理",
        path: typeof parsed.path === "string" ? parsed.path : "",
        isDir: parsed.isDir === true,
        turns: parsed.turns.filter(
          (t): t is AgentTurn =>
            !!t && typeof t === "object" && (t.role === "user" || t.role === "assistant") && typeof t.content === "string",
        ),
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      return { entries: [legacy] };
    }
    return { entries: [] };
  } catch {
    return { entries: [] };
  }
}

/** 写入/更新某会话的子代理列表；列表为空时视为“会话已删除”，物理删掉对应 json 文件。 */
export async function setSessionSubagents(sessionId: string, data: SessionSubagentChats): Promise<void> {
  const file = join(chatDir(), `${safeId(sessionId)}.json`);
  // 彻底清空（例如最后一个子代理被删除）时：删除持久化文件，而不残留空 json。
  if (Array.isArray(data.entries) && data.entries.length === 0) {
    await mkdir(chatDir(), { recursive: true });
    try {
      await unlink(file);
    } catch {
      /* 文件本就不存在则忽略 */
    }
    return;
  }
  await mkdir(chatDir(), { recursive: true });
  await writeFile(file, JSON.stringify({ entries: data.entries }, null, 2), "utf8");
}