/**
 * dsh-file-workbench — 子 agent 委派（host 端）。
 *
 * 复用宿主 harness 里已经注册的 `subagents` 服务（对应 @deepseek-ai/dsh-subagent
   * 的 `ctx.subagents` seam），把“当前选中的文件/文件夹 + 用户指令”作为一次
   * 一次性子 agent 的初始提示词下发。子 agent 以 fork 提供方派生——fork 以父会话
   * 已完成 turns 作为 seed 启动（这是宿主官方子代理工具走的通道，实测可用），
   * 并继承父会话的 agent-preset 组装（standard），获得文件/shell/网页等全套能力。
   * 注：早期用 spawn 通道，但宿主 dsh-subagent-in-process-driver 会把字符串 prompt
   * 直接塞进 user 消息 content，子 agent 第一步 `message.content.map` 抛 TypeError，
   * 故改用 fork 规避该宿主缺陷。
 *
 * 说明：本模块刻意不 import @deepseek-ai/dsh-subagent 的类型（宿主插件构建时
 * external、运行时经同 harness 解析）。服务以 `ctx.get('subagents')` 按名消费，
 * 并用最小结构类型承接返回对象；若宿主环境未启用该服务，返回可读错误，
 * 而不会拖垮整个工作台。
 */
import type { Context } from "@deepseek-ai/cordis";
import { readFile, stat } from "node:fs/promises";
import { basename } from "node:path";
import type { AgentTurn, SubagentDelegateResult } from "../shared/types.js";

/** 注入到子 agent 初始提示词里的文件正文上限（超出截断并提示）。 */
const MAX_CONTEXT_CHARS = 16000;

/** 读取目标文件的文本上下文（目录返回 undefined）。 */
async function readFileContext(path: string, isDir: boolean): Promise<string | undefined> {
  if (isDir) return undefined;
  let buf: Buffer;
  try {
    const st = await stat(path);
    if (!st.isFile()) return undefined;
    if (st.size > 4 * 1024 * 1024) return `[${basename(path)}] 文件过大（${st.size} bytes），未读取正文。`;
    buf = await readFile(path);
  } catch {
    return `[${basename(path)}] 无法读取文件内容。`;
  }
  let text = buf.toString("utf8");
  if (text.length > MAX_CONTEXT_CHARS) {
    text = text.slice(0, MAX_CONTEXT_CHARS) + `\n…[内容已截断，原文件共 ${buf.length} bytes]。`;
  }
  return text;
}

/**
 * 组装子 agent 的初始提示词：目标路径 + 指令 + （可选）文件正文。
 * `turns` 为本次会话历史（role: user/assistant），按顺序嵌入以保留上下文；
 * 文件正文只在会话第一轮（turns.length<=1）才随文注入，避免后续轮次重复消耗上下文。
 */
export function buildDelegatePrompt(
  path: string,
  isDir: boolean,
  turns: AgentTurn[],
  content?: string,
): string {
  const kind = isDir ? "文件夹" : "文件";
  const lines = [`当前处理目标${kind}：${path}`, `你是一个被文件工作台派来的子 agent，负责就地处理这个目标。`];
  // 只在首轮嵌入文件正文（作为只读参考快照）。
  if (content !== undefined) {
    lines.push(
      `\n目标${kind}的当前正文内容（只读参考快照，请自行读取/修改目标完成工作）：\n\`\`\`\n${content}\n\`\`\``,
    );
  }
  if (isDir) {
    lines.push(`\n注：目标是文件夹。你可以列目录、读取其中的文件，并在适当情况下创建/修改文件。工作目录即为该文件夹。`);
  }
  lines.push(`\n以下是与用户的对话记录（最新消息在最后）：`);
  const body = turns
    .map((turn, i) => `${turn.role === "user" ? "用户" : "子 agent"}#${i + 1}：\n${turn.content}`)
    .join("\n\n");
  lines.push(`--- 对话开始 ---\n${body}\n--- 对话结束 ---`);
  lines.push(
    `\n请回应用户最新的那条消息。如需改动代码/文件，请实际落盘后再总结改动与验证结果；不要编造未执行的操作。`,
  );
  return lines.join("\n");
}

/** 把任意错误尽量完整地文本化（含堆栈，便于前端定位“为什么报错”）。 */
function describeError(error: unknown): string {
  if (!(error instanceof Error)) return String(error);
  const stack = error.stack && error.stack.replace(/^\S+\s*/, "") ? `\n${error.stack}` : "";
  return `${error.message}${stack}`;
}

/** 调用 `ctx.subagents` 运行一次一次性 spawn 子 agent，返回其结果文本。 */
export async function delegateToSubagent(
  ctx: Context,
  opts: { path: string; isDir: boolean; turns: AgentTurn[]; sessionId?: string },
): Promise<SubagentDelegateResult> {
  // 1) 取 subagents 服务（可选消费，缺失返回可读错误，不影响插件加载）。
  let runtime: SubagentRuntimeLite | undefined;
  try {
    runtime = (ctx as { get?: (name: string) => unknown }).get?.("subagents") as SubagentRuntimeLite | undefined;
  } catch {
    /* ignore */
  }
  if (!runtime || typeof runtime.start !== "function") {
    return { output: "", error: "subagents 服务不可用：宿主未启用 dsh-subagent（@deepseek-ai/dsh-subagent 未加载）。" };
  }

  // 2) 读上下文并组装提示词（首轮才读文件正文）。
  const firstTurn = opts.turns.length <= 1;
  const content = firstTurn ? await readFileContext(opts.path, opts.isDir) : undefined;
  const prompt = buildDelegatePrompt(opts.path, opts.isDir, opts.turns, content);

  // 3) 解析父级活 Agent。fork/spawn 提供方用 parent.ctx.agents.create() 创建子 agent，
  //    fork 还读 parent.session 已完成 turns 作 seed —— 因此 request.parent
  //    必须是 agents 注册表里的“活”Agent（不能是注入探针/任意对象），子 agent
  //    也据此继承父会话的 agent-preset 组装（standard 能力）。
  const parent = resolveLiveParent(ctx, opts.sessionId);
  if (!parent) {
    return {
      output: "",
      error:
        "无法解析当前会话的“活”子 agent 父级：请在先进入一次聊天会话后重试（subagents 的 fork 需要以当前会话 agent 为父）",
    };
  }

  // 4) 构造请求。signal 为提供方必填；prompt 必须用内容块数组（[{"type":"text",text}]
  //    ）下发，这与宿主官方 dsh-tool-subagent 一致——若传纯字符串，宿主会把 user 消息
  //    content 留成字符串，子 agent 第一步 `message.content.map is not a function` 崩溃。
  const request: Record<string, unknown> = {
    prompt: [{ type: "text", text: prompt }],
    label: `workbench:${basename(opts.path)}`,
    maxDepth: 3,
    signal: new AbortController().signal,
    parent,
  };

  // 4) start → result → dispose，任一失败都透出真实错误便于定位。
  //    用 fork 提供方：官方子代理走的就是它，可规避 spawn 通道的字符串 content 缺陷。
  let run: SubagentRunLite;
  try {
    run = await runtime.start("fork", request as unknown as SubagentStartRequestLite);
  } catch (error) {
    return { output: "", error: `子 agent 委派失败：${describeError(error)}` };
  }
  try {
    const result = await run.result;
    const output = finalOutputText(result);
    // 无文字产出时：正常完成给兜底句当普通回复；异常终止则透出 error，
    // 前端会显示成 ✕ 报错而不是一片空白。
    const via = output ? { output } : describeEmptyOutput(result);
    const tokens = collectTokenUsage(run);
    return {
      runId: run.id,
      output: via.output,
      error: via.error,
      stopReason: result?.stopReason,
      diagnostic: result?.diagnostic,
      tokens,
    };
  } catch (error) {
    return { output: "", error: `子 agent 运行失败：${describeError(error)}` };
  } finally {
    try {
      await run.dispose?.();
    } catch {
      /* dispose 失败仅记录，不影响结果返回 */
    }
  }
}

/** 从子 agent 终态结果里取出可展示的最终文本。 */
export function finalOutputText(result: { output?: unknown; lastAssistantMessage?: unknown; stopReason?: string } | undefined): string {
  const pick = (chunk: unknown, acc: string[]): void => {
    if (chunk === undefined || chunk === null) return;
    if (typeof chunk === "string") {
      acc.push(chunk);
      return;
    }
    if (Array.isArray(chunk)) {
      for (const item of chunk) pick(item, acc);
      return;
    }
    if (typeof chunk === "object") {
      // 标准内容块：{ type:"text", text } 取 text；其余保留可读表示。
      const obj = chunk as Record<string, unknown>;
      if (obj.type === "text" && typeof obj.text === "string") acc.push(obj.text);
      else acc.push(JSON.stringify(chunk, null, 2));
      return;
    }
    acc.push(String(chunk));
  };

  const acc: string[] = [];
  pick(result?.lastAssistantMessage, acc);
  if (acc.length === 0) pick(result?.output, acc);
  // 只管提取纯文本：可能为空串；空输出的兜底/失败提示由调用方统一处理。
  return acc.join("\n").trim();
}

/**
 * 把“无文字产出”归一为可展示的结果：正常完成给兜底句；异常终止则返回可读错误，
 * 让调用方把真实终止原因（error/max-tokens/refusal/…）透出，而不是静默返回空串。
 */
export function describeEmptyOutput(
  result: { stopReason?: string; diagnostic?: string } | undefined,
): { output: string; error?: string } {
  const stop = result?.stopReason;
  if (stop === "completed" || !stop) {
    return { output: "(子 agent 已完成处理，但未返回文字内容)" };
  }
  const detail = result?.diagnostic ? `；诊断：${result.diagnostic}` : "";
  return { output: "", error: `子 agent 运行终止且未产出内容（原因：${stop}${detail}）` };
}

/**
 * 解析父级“活”Agent：优先按会话 id 从 `agents` 注册表取；缺省回退到当前活跃 agent。
 * 仅当解析到带 `.options`（能供 resolveChildDepth 读取 subagentDepth）的真实 Agent 才返回。
 */
export function resolveLiveParent(ctx: Context, sessionId?: string): unknown {
  let agents: { get?: (id: string) => unknown; current?: unknown; active?: unknown } | undefined;
  try {
    const c = ctx as unknown as { get?: (name: string) => unknown; agents?: unknown };
    agents = (c.get?.("agents") ?? c.agents) as typeof agents | undefined;
  } catch {
    /* ignore */
  }
  if (!agents) return undefined;
  const hasOptions = (agent: unknown): agent is Record<string, unknown> =>
    !!agent && typeof agent === "object" && !!((agent as Record<string, unknown>).options);
  if (sessionId && typeof agents.get === "function") {
    const byId = agents.get(sessionId);
    if (hasOptions(byId)) return byId;
  }
  for (const key of ["current", "active"] as const) {
    const via = agents[key];
    if (typeof via === "function") {
      try {
        const resolved = (via as () => unknown)();
        if (hasOptions(resolved)) return resolved;
      } catch {
        /* ignore */
      }
    }
  }
  return undefined;
}

/** 本地最小接缝类型（不 import dsh-subagent 真实类型，防模块解析失败）。 */
export interface SubagentRunLite {
  id: string;
  result: Promise<{
    output?: unknown;
    lastAssistantMessage?: unknown;
    stopReason?: string;
    diagnostic?: string;
  }>;
  dispose?: () => Promise<void>;
  /** 子 agent 本体（宿主 in-process driver 挂的 localAgent），仅作诊断读取会话事件。 */
  localAgent?: { session?: { events?: unknown[] } };
}

interface SubagentStartRequestLite {
  prompt: Array<{ type: string; text: string }>;
  label?: string;
  maxDepth?: number;
  signal: AbortSignal;
  parent: unknown;
}

export interface SubagentRuntimeLite {
  start(name: string, request: SubagentStartRequestLite): Promise<SubagentRunLite>;
}

/** 从 usage 对象提取 token 总数（兼容多种用法，非数字/缺失返回 0）。 */
function usageTokens(usage: unknown): number {
  if (!usage || typeof usage !== "object") return 0;
  const u = usage as Record<string, unknown>;
  const num = (v: unknown): number => (typeof v === "number" && Number.isFinite(v) && v > 0 ? Math.round(v) : 0);
  const input = num(u.prompt_tokens) + num(u.input_tokens) || num(u.inputTokens) || num(u.promptTokens);
  const output = num(u.completion_tokens) || num(u.output_tokens) || num(u.outputTokens) || num(u.completionTokens);
  const total = num(u.total_tokens) || num(u.totalTokens) || input + output;
  return total;
}

/** 累加子 agent 会话里各条 assistant/message 事件附加的 usage，得出本次运行总 token。 */
export function collectTokenUsage(run: SubagentRunLite): number | undefined {
  try {
    const child = (run as unknown as { localAgent?: { session?: { events?: unknown[] } } }).localAgent;
    const events = child?.session?.events;
    if (!Array.isArray(events)) return undefined;
    let sum = 0;
    let seen = 0;
    for (const e of events as { type?: string; data?: { usage?: unknown } }[]) {
      if (e?.type === "assistant/message" && e.data) {
        const t = usageTokens(e.data.usage);
        if (t > 0) {
          sum += t;
          seen++;
        }
      }
    }
    return seen > 0 ? sum : undefined;
  } catch {
    return undefined;
  }
}