/**
 * fs-read —— 打开/读取单个文件，推导浏览类型（对应 dsh-better-sidebar 的 read/preview 服务）。
 *
 * 文本/代码按 UTF-8 读；图片读成 dataURL 交给浏览器；未知/超大二进制拒绝。所有读取
 * 先经过 root containment 守卫（fs-tree.ensureWsPath），杜绝路径穿越与越权。
 */
import { basename, dirname, extname } from "node:path";
import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import type { FileKind, OpenResult } from "../shared/types.js";
import { FsError, ensureWsPath, ensureWsWritePath, requireAbsolute } from "./fs-tree.js";

/** 文本文件上限（超出拒绝，避免超大文件拖垮渲染）。 */
export const MAX_TEXT_SIZE = 4 * 1024 * 1024;
/** 图片文件上限。 */
export const MAX_IMAGE_SIZE = 16 * 1024 * 1024;
/** 二进制文档（PDF 等）上限。 */
export const MAX_DOC_SIZE = 32 * 1024 * 1024;
/** 音视频预览 base64 上限（超出回退为下载）。 */
export const MAX_MEDIA_SIZE = 64 * 1024 * 1024;

/** 代码/文本扩展名 → 折叠语言名（供编辑器后续高亮；非必需元数据）。 */
export function languageOf(name: string): string | undefined {
  const e = extname(name).toLowerCase();
  const map: Record<string, string> = {
    ".ts": "typescript",
    ".tsx": "tsx",
    ".js": "javascript",
    ".jsx": "jsx",
    ".mjs": "javascript",
    ".cjs": "javascript",
    ".json": "json",
    ".py": "python",
    ".go": "go",
    ".rs": "rust",
    ".java": "java",
    ".c": "c",
    ".h": "c",
    ".cpp": "cpp",
    ".css": "css",
    ".scss": "scss",
    ".html": "html",
    ".xml": "xml",
    ".yml": "yaml",
    ".yaml": "yaml",
    ".toml": "toml",
    ".sh": "shell",
    ".md": "markdown",
    ".sql": "sql",
  };
  return map[e];
}

const IMAGE_EXT = new Set([".png", ".jpg", ".jpeg", ".gif", ".svg", ".webp", ".bmp", ".ico"]);
const AUDIO_EXT = new Set([".mp3", ".wav", ".ogg", ".flac", ".m4a", ".aac", ".wma", ".opus", ".mid", ".midi"]);
const VIDEO_EXT = new Set([".mp4", ".webm", ".mov", ".mkv", ".avi", ".m4v", ".ogv", ".mpg", ".mpeg", ".wmv", ".3gp"]);

/**
 * 按绝对路径读取一个文件为 OpenResult。
 * @throws FsError 当越权/不存在/超大小/不可读。
 */
export async function readOpenResult(root: string, target: string): Promise<OpenResult> {
  const safe = await ensureWsPath(root, target);
  return readResolvedFile(safe, target);
}

/**
 * 只读打开任意绝对文件（“我的电脑”浏览用，不做工作区 containment 守卫）。
 * 仍要求绝对路径、存在、是文件、大小受限。
 */
export async function readArbitrary(target: string): Promise<OpenResult> {
  const safe = requireAbsolute(target);
  return readResolvedFile(safe, target);
}

/** 对一个已解析（已 stat/规范化）的安全绝对路径做内容读取。 */
async function readResolvedFile(safe: string, displayPath: string): Promise<OpenResult> {
  const s = await stat(safe).catch((error) => {
    throw new FsError("not-found", `cannot stat "${displayPath}": ${error instanceof Error ? error.message : String(error)}`, 404);
  });
  if (!s.isFile()) throw new FsError("bad-request", `"${displayPath}" is not a file`, 400);

  const name = basename(safe);
  const e = extname(safe).toLowerCase();

  if (e === ".md" || e === ".markdown") {
    return { name, path: safe, kind: "markdown", text: await readText(safe, name), size: s.size, language: "markdown" };
  }
  if (e === ".html" || e === ".htm") {
    return { name, path: safe, kind: "html", text: await readText(safe, name), size: s.size, language: "html" };
  }
  if (e === ".csv" || e === ".tsv") {
    const kind = e === ".csv" ? "csv" : "tsv";
    return { name, path: safe, kind, text: await readText(safe, name), size: s.size, language: kind };
  }
  if (e === ".json" || e === ".jsonc") {
    return { name, path: safe, kind: "json", text: await readText(safe, name), size: s.size, language: "json" };
  }
  if (IMAGE_EXT.has(e)) {
    const buffer = await readFile(safe).catch((error) => {
      throw new FsError("fs-error", `cannot read "${displayPath}": ${error instanceof Error ? error.message : String(error)}`, 400);
    });
    if (buffer.length > MAX_IMAGE_SIZE) throw new FsError("too-large", `image exceeds the ${MAX_IMAGE_SIZE} byte limit`, 400);
    const mime = `image/${e === ".svg" ? "svg+xml" : (e === ".jpg" ? "jpeg" : e.slice(1))}`;
    return {
      name,
      path: safe,
      kind: "image",
      imageDataUrl: `data:${mime};base64,${buffer.toString("base64")}`,
      size: buffer.length,
    };
  }
  // PDF：读成 base64 dataURL，交给浏览器原生查看器。
  if (e === ".pdf") {
    const buffer = await readFile(safe).catch((error) => {
      throw new FsError("fs-error", `cannot read "${displayPath}": ${error instanceof Error ? error.message : String(error)}`, 400);
    });
    if (buffer.length > MAX_DOC_SIZE) throw new FsError("too-large", `pdf exceeds the ${MAX_DOC_SIZE} byte limit`, 400);
    return {
      name,
      path: safe,
      kind: "pdf",
      dataUrl: `data:application/pdf;base64,${buffer.toString("base64")}`,
      size: buffer.length,
    };
  }
  // 音频：base64 dataURL 交给浏览器内播放（超大则回退下载）。
  if (AUDIO_EXT.has(e)) {
    const buffer = await readFile(safe).catch((error) => {
      throw new FsError("fs-error", `cannot read "${displayPath}": ${error instanceof Error ? error.message : String(error)}`, 400);
    });
    if (buffer.length > MAX_MEDIA_SIZE) return { name, path: safe, kind: "download", size: buffer.length };
    return { name, path: safe, kind: "audio", dataUrl: `data:audio/${e.slice(1)};base64,${buffer.toString("base64")}`, size: buffer.length };
  }
  // 视频：base64 dataURL 浏览器内播放（超大则回退下载）。
  if (VIDEO_EXT.has(e)) {
    const buffer = await readFile(safe).catch((error) => {
      throw new FsError("fs-error", `cannot read "${displayPath}": ${error instanceof Error ? error.message : String(error)}`, 400);
    });
    if (buffer.length > MAX_MEDIA_SIZE) return { name, path: safe, kind: "download", size: buffer.length };
    return { name, path: safe, kind: "video", dataUrl: `data:video/${e.slice(1)};base64,${buffer.toString("base64")}`, size: buffer.length };
  }
  // 其余所有格式：能按文本读则编辑，否则归为“下载”兜底（不再 400）。
  try {
    const text = await readText(safe, name);
    return { name, path: safe, kind: "text", text, size: s.size, language: languageOf(name) };
  } catch {
    return { name, path: safe, kind: "download", size: s.size };
  }
}

async function readText(safe: string, name: string): Promise<string> {
  const s = await stat(safe);
  if (s.size > MAX_TEXT_SIZE) throw new FsError("too-large", `file exceeds the ${MAX_TEXT_SIZE} byte text limit`, 400);
  const buf = await readFile(safe);
  // 粗判是否明显是二进制（大量 NUL）——扩展名没覆盖到的二进制保护。
  if (containsBinary(buf)) {
    throw new FsError("bad-request", `"${name}" looks like a binary file`, 400);
  }
  return buf.toString("utf8");
}

function containsBinary(buf: Buffer): boolean {
  const probe = buf.subarray(0, Math.min(buf.length, 8192));
  let nul = 0;
  for (const b of probe) if (b === 0) nul += 1;
  return nul > probe.length * 0.01;
}

/** 保存文本到文件（root 之内，必要时创建父目录）。 */
export async function saveText(root: string, target: string, content: string): Promise<string> {
  const safe = await ensureWsWritePath(root, target);
  await mkdir(dirname(safe), { recursive: true });
  await writeFile(safe, content, "utf8");
  return safe;
}

/** 文本类型导出占位。 */
export type { FileKind };